parameters.query:
SELECT json_build_object(
  'users', COALESCE((
    SELECT json_agg(row_to_json(u))
    FROM (
      SELECT id, email, username, "favoriteTeamId", "isAdmin",
             "isApproved", "hasPaid", "invitedBy", "createdAt"
      FROM "User" ORDER BY id
    ) u
  ), '[]'::json),
  'predictions', COALESCE((
    SELECT json_agg(row_to_json(p))
    FROM (
      SELECT id, "userId", "matchId", "homeGoals", "awayGoals",
             points, "createdAt", "updatedAt"
      FROM "Prediction" ORDER BY id
    ) p
  ), '[]'::json),
  'matches', COALESCE((
    SELECT json_agg(row_to_json(m))
    FROM (
      SELECT id, "fechaId", "homeTeamId", "awayTeamId", "scheduledAt",
             "homeScore", "awayScore", "isFinished"
      FROM "Match" ORDER BY id
    ) m
  ), '[]'::json),
  'fechas', COALESCE((
    SELECT json_agg(row_to_json(f))
    FROM (
      SELECT id, number, season, phase, "isActive", deadline
      FROM "Fecha" ORDER BY id
    ) f
  ), '[]'::json),
  'support_requests', COALESCE((
    SELECT json_agg(row_to_json(s))
    FROM (
      SELECT id, email, message, "isResolved", "createdAt"
      FROM "SupportRequest" ORDER BY id
    ) s
  ), '[]'::json)
) AS backup;

parameters.jsCode:
const data = $input.first().json.backup;
const meta = $('Set: Backup Metadata').first().json;

const matrix = [];

const addTable = (label, rows, columns) => {
  const r = rows || [];
  matrix.push([`### ${label.toUpperCase()} (${r.length} filas) ###`]);
  matrix.push(columns);
  for (const row of r) {
    matrix.push(columns.map(c => {
      const v = row[c];
      if (v === null || v === undefined) return "";
      if (typeof v === "object") return JSON.stringify(v);
      return v;
    }));
  }
  matrix.push([]);
};

addTable("Users", data.users,
  ["id", "email", "username", "favoriteTeamId", "isAdmin",
   "isApproved", "hasPaid", "invitedBy", "createdAt"]);
addTable("Predictions", data.predictions,
  ["id", "userId", "matchId", "homeGoals", "awayGoals",
   "points", "createdAt", "updatedAt"]);
addTable("Matches", data.matches,
  ["id", "fechaId", "homeTeamId", "awayTeamId", "scheduledAt",
   "homeScore", "awayScore", "isFinished"]);
addTable("Fechas", data.fechas,
  ["id", "number", "season", "phase", "isActive", "deadline"]);
addTable("Support Requests", data.support_requests,
  ["id", "email", "message", "isResolved", "createdAt"]);

return [{
  json: {
    sheetName: meta.sheetName,
    spreadsheetId: meta.spreadsheetId,
    values: matrix,
    rowCount: matrix.length,
  },
}];
